void inputInt(int &val) {
    char c;
    val = 0;
    bool isNegative = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') isNegative = true;
    }
    do {
        val = val * 10 + (c - '0');
    } while (isdigit(c = getchar()));
    if (isNegative) val = -val;
}

void inputLL(long long &val) {
    char c;
    val = 0;
    bool isNegative = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') isNegative = true;
    }
