long long n, k, MOD;
int fact[262155];
int invFact[262155];

int modPow(int base, long long exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (long long)res * base % MOD;
        }
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int memoTable[262155][31];
bool visitedTable[262155][31];
int bitLog[262155];

int countTwos(int x) {
    int cnt = 0;
    while (x && (x & 1) == 0) {
        ++cnt;
        x >>= 1;
    }
    return cnt;
}

int twoSum[262155];

int nCr(int N, int M) {
    return (long long)fact[N] * invFact[M] % MOD * invFact[N - M] % MOD;
}

int topDown(int N, int K) {
    if (N == 0) return 1;
    if (K == 0) return 0;
    if (memoTable[N][K] != -1) return memoTable[N][K];

    int step = 1 << bitLog[N];
    int sum = 0;
    for (int i = N; i >= step; i -= 2) {
        sum = (sum + (long long)nCr(N, i) * topDown(N - i, K - 1) % MOD * K) % MOD;
    }
    return memoTable[N][K] = sum;
}

vector<pair<int, int>> processingOrder;

int bottomUp(int N, int K) {
    queue<pair<int, int>> q;
    q.push({N, K});

    while (!q.empty()) {
        int curN = q.front().first;
        int curK = q.front().second;
        q.pop();
        processingOrder.push_back({curN, curK});

        if (curN == 0 || curK == 0) continue;

        int step = 1 << bitLog[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoSum[i] + twoSum[curN - i] == twoSum[curN] && !visitedTable[curN - i][curK - 1]) {
                visitedTable[curN - i][curK - 1] = true;
                q.push({curN - i, curK - 1});
            }
        }
    }

    for (int i = processingOrder.size() - 1; i >= 0; --i) {
        int curN = processingOrder[i].first;
        int curK = processingOrder[i].second;

        if (curN == 0) {
            memoTable[curN][curK] = 1;
            continue;
        }
        if (curK == 0) {
            memoTable[curN][curK] = 0;
            continue;
        }

        int step = 1 << bitLog[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoSum[i] + twoSum[curN - i] == twoSum[curN]) {
                memoTable[curN][curK] = (memoTable[curN][curK] + (long long)nCr(curN, i) * memoTable[curN - i][curK - 1] % MOD * curK) % MOD;
            }
        }
    }

    return memoTable[N][K];
}

