        fact[i] = (long long)fact[i - 1] * i % MOD;
        bitLog[i] = bitLog[i >> 1] + 1;
        twoSum[i] = twoSum[i - 1] + countTwos(i);
    }

    invFact[262150] = modPow(fact[262150], MOD - 2);
    for (int i = 262149; i >= 1; --i) {
        invFact[i] = (long long)invFact[i + 1] * (i + 1) % MOD;
    }

    invFact[0] = invFact[1];

    if (n & 1) {
        cout << modPow(k, n) << '\n';
    } else {
        int total = modPow(k, n);
        int result = bottomUp(n, k);
        cout << ((total - result) % MOD + MOD) % MOD;
    }
}
